import React from "react";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import "./App.css";
import Home from "./components/Home/Home";
import Nav from "./components/Nav/Nav";
import AddOrder from "./components/AddOrder/AddOrder";
import OrderUpdate from "./components/AddOrder/UpdateOrder";
import AllOrders from "./components/AddOrder/AllOrders";

function App() {
  const location = useLocation(); // Get the current location

  return (
    <Router>
      <div>
        {location.pathname !== "/add-order" && <Nav />} {/* Conditionally render Nav */}
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/mainhome" element={<Home />} />
          <Route path="/add-order" element={<AddOrder />} />
          <Route path="/all-orders" element={<AllOrders />} />
          <Route path="/update-order" element={<OrderUpdate />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
